/* StayQuest Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --blue: #006CE4;
  --gold: #FFB700;
  --white: #ffffff;
  --gray-50: #f5f5f5;
  --gray-100: #ebebeb;
  --gray-200: #d9d9d9;
  --gray-300: #bdbdbd;
  --gray-500: #6b6b6b;
  --gray-700: #333333;
  --gray-900: #1a1a1a;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 2px 8px rgba(0,0,0,.12);
  --shadow-lg: 0 4px 16px rgba(0,0,0,.16);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

/* Container */
.container { max-width: 1120px; margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.site-header {
  background: var(--navy);
  padding: 16px 0 0;
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 16px;
}
.logo {
  font-size: 24px;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.5px;
}
.header-actions { display: flex; gap: 8px; align-items: center; }
.header-actions .btn-outline {
  background: transparent;
  color: var(--white);
  border: 1px solid rgba(255,255,255,.4);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}
.header-actions .btn-outline:hover { background: rgba(255,255,255,.1); }
.header-actions .btn-register {
  background: var(--white);
  color: var(--blue);
  border: none;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
}
.header-actions .btn-register:hover { background: var(--gray-100); }

/* Navigation tabs */
.nav-tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 0;
}
.nav-tabs::-webkit-scrollbar { display: none; }
.nav-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 20px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--white);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
  text-decoration: none;
}
.nav-tab:hover { background: rgba(255,255,255,.1); text-decoration: none; }
.nav-tab.active {
  border-color: var(--white);
  background: rgba(255,255,255,.15);
}
.nav-tab svg { width: 20px; height: 20px; flex-shrink: 0; }

/* ===== HERO ===== */
.hero {
  background: var(--navy);
  padding: 32px 0 48px;
  color: var(--white);
}
.hero h1 { font-size: 36px; font-weight: 800; margin-bottom: 8px; }
.hero .subtitle { font-size: 18px; font-weight: 400; opacity: .9; margin-bottom: 32px; }

/* Search bar */
.search-bar {
  background: var(--gold);
  border-radius: var(--radius-md);
  padding: 4px;
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.search-field {
  flex: 1;
  min-width: 160px;
  background: var(--white);
  border: none;
  border-radius: var(--radius-sm);
  padding: 14px 16px;
  font-size: 15px;
  color: var(--gray-900);
  outline: none;
}
.search-field::placeholder { color: var(--gray-500); }
.search-btn {
  background: var(--blue);
  color: var(--white);
  border: none;
  border-radius: var(--radius-sm);
  padding: 14px 28px;
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition);
}
.search-btn:hover { background: #0057b8; }
.search-options {
  display: flex;
  gap: 20px;
  margin-top: 12px;
}
.search-options label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--white);
  font-size: 14px;
  cursor: pointer;
}
.search-options input[type="checkbox"],
.search-options input[type="radio"] { accent-color: var(--blue); width: 18px; height: 18px; }

/* Radio group for packages */
.radio-group {
  display: flex;
  gap: 20px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.radio-group label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--white);
  font-size: 14px;
  cursor: pointer;
  padding: 8px 16px;
  border-radius: 20px;
  border: 1px solid rgba(255,255,255,.3);
  transition: all var(--transition);
}
.radio-group label:has(input:checked) {
  background: rgba(255,255,255,.2);
  border-color: var(--white);
}
.radio-group input[type="radio"] { accent-color: var(--white); }

/* ===== SECTIONS ===== */
.section { padding: 48px 0; }
.section-alt { background: var(--gray-50); }
.section-title { font-size: 24px; font-weight: 700; margin-bottom: 4px; }
.section-subtitle { font-size: 16px; color: var(--gray-500); margin-bottom: 24px; }

/* ===== TRUST BADGES ===== */
.trust-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}
.trust-card {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.trust-icon {
  width: 48px;
  height: 48px;
  background: var(--blue);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--white);
}
.trust-card h3 { font-size: 15px; font-weight: 700; margin-bottom: 4px; }
.trust-card p { font-size: 13px; color: var(--gray-500); line-height: 1.4; }

/* ===== OFFERS ===== */
.offers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.offer-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: box-shadow var(--transition);
}
.offer-card:hover { box-shadow: var(--shadow-md); }
.offer-card h3 { font-size: 18px; font-weight: 700; }
.offer-card p { font-size: 14px; color: var(--gray-500); line-height: 1.5; }

/* ===== BUTTONS ===== */
.btn-primary {
  display: inline-block;
  background: var(--blue);
  color: var(--white);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  border: none;
  transition: background var(--transition);
  text-decoration: none;
}
.btn-primary:hover { background: #0057b8; text-decoration: none; }
.btn-secondary {
  display: inline-block;
  background: var(--white);
  color: var(--blue);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  border: 1px solid var(--blue);
  transition: all var(--transition);
  text-decoration: none;
}
.btn-secondary:hover { background: #e8f0fe; text-decoration: none; }
.btn-gold {
  display: inline-block;
  background: var(--gold);
  color: var(--gray-900);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 700;
  border: none;
  transition: background var(--transition);
  text-decoration: none;
}
.btn-gold:hover { background: #e6a500; text-decoration: none; }

/* ===== PROPERTY TYPE PILLS ===== */
.type-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.type-pill {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 20px;
  padding: 8px 18px;
  font-size: 14px;
  color: var(--blue);
  font-weight: 500;
  transition: all var(--transition);
  text-decoration: none;
}
.type-pill:hover {
  background: #e8f0fe;
  border-color: var(--blue);
  text-decoration: none;
}

/* ===== TABS (generic) ===== */
.tabs-bar {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 4px;
}
.tabs-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 20px;
  border-radius: 20px;
  border: 1px solid var(--gray-200);
  background: var(--white);
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-700);
  white-space: nowrap;
  transition: all var(--transition);
  cursor: pointer;
}
.tab-btn:hover { border-color: var(--blue); color: var(--blue); }
.tab-btn.active {
  background: var(--blue);
  color: var(--white);
  border-color: var(--blue);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== DESTINATION / PROPERTY CARDS ===== */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}
.card-grid-3 { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); }
.card-grid-5 { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
.dest-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-100);
  transition: box-shadow var(--transition), transform var(--transition);
}
.dest-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.dest-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #cdd5e0 0%, #a8b5c8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
  font-size: 13px;
  font-weight: 500;
  position: relative;
  overflow: hidden;
}
.dest-card-img::after {
  content: attr(data-label);
  position: absolute;
  font-size: 12px;
  color: var(--white);
  background: rgba(0,0,0,.35);
  padding: 4px 10px;
  border-radius: 4px;
}
.dest-card-body { padding: 16px; }
.dest-card-body h3 { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.dest-card-body .location { font-size: 13px; color: var(--gray-500); margin-bottom: 8px; }
.dest-card-body .meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.rating-badge {
  background: var(--navy);
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  line-height: 1;
}
.rating-text { font-size: 13px; color: var(--gray-500); }
.price-line { margin-top: 10px; text-align: right; }
.price-original {
  font-size: 13px;
  color: var(--gray-500);
  text-decoration: line-through;
  margin-right: 4px;
}
.price-current { font-size: 18px; font-weight: 700; color: var(--gray-900); }
.price-note { font-size: 12px; color: var(--gray-500); }
.duration-badge {
  background: #e8f0fe;
  color: var(--blue);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
}

/* ===== CAROUSEL ===== */
.carousel-wrapper {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 4px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track .dest-card { min-width: 260px; flex-shrink: 0; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--gray-200);
  background: var(--white);
  box-shadow: var(--shadow-md);
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: all var(--transition);
  color: var(--gray-700);
}
.carousel-btn:hover { background: var(--gray-50); box-shadow: var(--shadow-lg); }
.carousel-btn.prev { left: 8px; }
.carousel-btn.next { right: 8px; }

/* ===== TRENDING / SIMPLE CARDS ===== */
.trending-grid {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.trending-card {
  flex: 1;
  min-width: 180px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #2d5a9e 0%, #1a3a6e 100%);
  display: flex;
  align-items: flex-end;
  transition: transform var(--transition);
}
.trending-card:hover { transform: scale(1.02); }
.trending-card span {
  padding: 16px;
  color: var(--white);
  font-size: 20px;
  font-weight: 700;
  text-shadow: 0 2px 8px rgba(0,0,0,.4);
  width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,.45));
}

/* Explore dest compact */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.explore-item {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-100);
  transition: box-shadow var(--transition);
}
.explore-item:hover { box-shadow: var(--shadow-sm); }
.explore-thumb {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, #cdd5e0 0%, #a8b5c8 100%);
  flex-shrink: 0;
}
.explore-info h3 { font-size: 15px; font-weight: 600; }
.explore-info p { font-size: 13px; color: var(--gray-500); }

/* ===== LOYALTY CTA ===== */
.loyalty-banner {
  background: linear-gradient(135deg, var(--navy) 0%, #004bb5 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.loyalty-banner h2 { font-size: 28px; font-weight: 800; margin-bottom: 4px; }
.loyalty-banner h3 { font-size: 18px; font-weight: 600; margin-bottom: 8px; opacity: .9; }
.loyalty-banner p { font-size: 14px; opacity: .8; max-width: 500px; }
.loyalty-actions { display: flex; gap: 12px; margin-top: 16px; }

/* ===== POPULAR LINKS ===== */
.links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
}
.links-grid a {
  font-size: 14px;
  color: var(--blue);
  padding: 4px 0;
}

/* ===== FAQ ACCORDION ===== */
.accordion { max-width: 800px; }
.accordion-item {
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  margin-bottom: 8px;
  overflow: hidden;
}
.accordion-header {
  width: 100%;
  background: var(--white);
  border: none;
  padding: 18px 20px;
  font-size: 15px;
  font-weight: 600;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  transition: background var(--transition);
}
.accordion-header:hover { background: var(--gray-50); }
.accordion-chevron {
  width: 20px;
  height: 20px;
  transition: transform 0.3s ease;
  flex-shrink: 0;
  color: var(--gray-500);
}
.accordion-item.open .accordion-chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.accordion-item.open .accordion-body {
  max-height: 300px;
  padding: 0 20px 18px;
}
.accordion-body p { font-size: 14px; color: var(--gray-500); line-height: 1.6; }

/* ===== RENTAL COMPANIES ===== */
.company-grid {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}
.company-logo {
  width: 120px;
  height: 60px;
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--gray-700);
  transition: box-shadow var(--transition);
}
.company-logo:hover { box-shadow: var(--shadow-sm); }

/* ===== CREDIT CARD PROMO ===== */
.promo-banner {
  background: linear-gradient(135deg, #003B95 0%, #0057b8 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.promo-banner h3 { font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.promo-banner p { font-size: 14px; opacity: .85; }

/* ===== ATTRACTIONS ACTIVITY CARDS ===== */
.activity-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-100);
  transition: box-shadow var(--transition), transform var(--transition);
}
.activity-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.activity-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #e0c8a8 0%, #c4a882 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  color: var(--gray-500);
}
.activity-card-body { padding: 16px; }
.activity-card-body h3 { font-size: 14px; font-weight: 600; line-height: 1.4; }
.activity-card-body .from-price { font-size: 13px; color: var(--gray-500); margin-top: 8px; }
.activity-card-body .from-price strong { color: var(--gray-900); }

/* ===== BENEFITS SECTION ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-100);
}
.benefit-icon {
  width: 56px;
  height: 56px;
  background: #e8f0fe;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  color: var(--blue);
}
.benefit-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--gray-500); }

/* ===== ACCOUNT CTA ===== */
.account-banner {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
}
.account-banner h2 { font-size: 24px; font-weight: 700; margin-bottom: 4px; }
.account-banner .sub { font-size: 16px; color: var(--gray-500); margin-bottom: 8px; }
.account-banner p { font-size: 14px; color: var(--gray-500); margin-bottom: 20px; }
.account-actions { display: flex; gap: 12px; justify-content: center; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,.8);
  padding: 48px 0 24px;
  font-size: 13px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  color: var(--white);
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  color: rgba(255,255,255,.7);
  padding: 4px 0;
  font-size: 13px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); text-decoration: none; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.15);
  padding-top: 24px;
  text-align: center;
  font-size: 12px;
  opacity: .6;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .hero h1 { font-size: 26px; }
  .search-bar { flex-direction: column; }
  .search-field { min-width: 100%; }
  .loyalty-banner { padding: 24px; text-align: center; justify-content: center; }
  .loyalty-actions { justify-content: center; }
  .promo-banner { flex-direction: column; text-align: center; }
  .trending-grid { flex-direction: column; }
  .trending-card { aspect-ratio: 16/7; }
  .card-grid { grid-template-columns: 1fr 1fr; }
  .explore-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .header-actions .btn-outline.hide-mobile { display: none; }
}
@media (max-width: 480px) {
  .card-grid { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: 1fr; }
  .radio-group { flex-direction: column; gap: 8px; }
}

/* StayQuest Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --blue: #006CE4;
  --gold: #FFB700;
  --white: #ffffff;
  --gray-50: #f5f5f5;
  --gray-100: #ebebeb;
  --gray-200: #d9d9d9;
  --gray-300: #bdbdbd;
  --gray-500: #6b6b6b;
  --gray-700: #333333;
  --gray-900: #1a1a1a;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 2px 8px rgba(0,0,0,.12);
  --shadow-lg: 0 4px 16px rgba(0,0,0,.16);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

/* Container */
.container { max-width: 1120px; margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.site-header {
  background: var(--navy);
  padding: 16px 0 0;
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 16px;
}
.logo {
  font-size: 24px;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.5px;
}
.header-actions { display: flex; gap: 8px; align-items: center; }
.header-actions .btn-outline {
  background: transparent;
  color: var(--white);
  border: 1px solid rgba(255,255,255,.4);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}
.header-actions .btn-outline:hover { background: rgba(255,255,255,.1); }
.header-actions .btn-register {
  background: var(--white);
  color: var(--blue);
  border: none;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
}
.header-actions .btn-register:hover { background: var(--gray-100); }

/* Navigation tabs */
.nav-tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 0;
}
.nav-tabs::-webkit-scrollbar { display: none; }
.nav-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 20px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--white);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
  text-decoration: none;
}
.nav-tab:hover { background: rgba(255,255,255,.1); text-decoration: none; }
.nav-tab.active {
  border-color: var(--white);
  background: rgba(255,255,255,.15);
}
.nav-tab svg { width: 20px; height: 20px; flex-shrink: 0; }

/* ===== HERO ===== */
.hero {
  background: var(--navy);
  padding: 32px 0 48px;
  color: var(--white);
}
.hero h1 { font-size: 36px; font-weight: 800; margin-bottom: 8px; }
.hero .subtitle { font-size: 18px; font-weight: 400; opacity: .9; margin-bottom: 32px; }

/* Search bar */
.search-bar {
  background: var(--gold);
  border-radius: var(--radius-md);
  padding: 4px;
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.search-field {
  flex: 1;
  min-width: 160px;
  background: var(--white);
  border: none;
  border-radius: var(--radius-sm);
  padding: 14px 16px;
  font-size: 15px;
  color: var(--gray-900);
  outline: none;
}
.search-field::placeholder { color: var(--gray-500); }
.search-btn {
  background: var(--blue);
  color: var(--white);
  border: none;
  border-radius: var(--radius-sm);
  padding: 14px 28px;
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition);
}
.search-btn:hover { background: #0057b8; }
.search-options {
  display: flex;
  gap: 20px;
  margin-top: 12px;
}
.search-options label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--white);
  font-size: 14px;
  cursor: pointer;
}
.search-options input[type="checkbox"],
.search-options input[type="radio"] { accent-color: var(--blue); width: 18px; height: 18px; }

/* Radio group for packages */
.radio-group {
  display: flex;
  gap: 20px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.radio-group label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--white);
  font-size: 14px;
  cursor: pointer;
  padding: 8px 16px;
  border-radius: 20px;
  border: 1px solid rgba(255,255,255,.3);
  transition: all var(--transition);
}
.radio-group label:has(input:checked) {
  background: rgba(255,255,255,.2);
  border-color: var(--white);
}
.radio-group input[type="radio"] { accent-color: var(--white); }

/* ===== SECTIONS ===== */
.section { padding: 48px 0; }
.section-alt { background: var(--gray-50); }
.section-title { font-size: 24px; font-weight: 700; margin-bottom: 4px; }
.section-subtitle { font-size: 16px; color: var(--gray-500); margin-bottom: 24px; }

/* ===== TRUST BADGES ===== */
.trust-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}
.trust-card {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.trust-icon {
  width: 48px;
  height: 48px;
  background: var(--blue);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--white);
}
.trust-card h3 { font-size: 15px; font-weight: 700; margin-bottom: 4px; }
.trust-card p { font-size: 13px; color: var(--gray-500); line-height: 1.4; }

/* ===== OFFERS ===== */
.offers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.offer-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: box-shadow var(--transition);
}
.offer-card:hover { box-shadow: var(--shadow-md); }
.offer-card h3 { font-size: 18px; font-weight: 700; }
.offer-card p { font-size: 14px; color: var(--gray-500); line-height: 1.5; }

/* ===== BUTTONS ===== */
.btn-primary {
  display: inline-block;
  background: var(--blue);
  color: var(--white);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  border: none;
  transition: background var(--transition);
  text-decoration: none;
}
.btn-primary:hover { background: #0057b8; text-decoration: none; }
.btn-secondary {
  display: inline-block;
  background: var(--white);
  color: var(--blue);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  border: 1px solid var(--blue);
  transition: all var(--transition);
  text-decoration: none;
}
.btn-secondary:hover { background: #e8f0fe; text-decoration: none; }
.btn-gold {
  display: inline-block;
  background: var(--gold);
  color: var(--gray-900);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 700;
  border: none;
  transition: background var(--transition);
  text-decoration: none;
}
.btn-gold:hover { background: #e6a500; text-decoration: none; }

/* ===== PROPERTY TYPE PILLS ===== */
.type-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.type-pill {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 20px;
  padding: 8px 18px;
  font-size: 14px;
  color: var(--blue);
  font-weight: 500;
  transition: all var(--transition);
  text-decoration: none;
}
.type-pill:hover {
  background: #e8f0fe;
  border-color: var(--blue);
  text-decoration: none;
}

/* ===== TABS (generic) ===== */
.tabs-bar {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 4px;
}
.tabs-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 20px;
  border-radius: 20px;
  border: 1px solid var(--gray-200);
  background: var(--white);
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-700);
  white-space: nowrap;
  transition: all var(--transition);
  cursor: pointer;
}
.tab-btn:hover { border-color: var(--blue); color: var(--blue); }
.tab-btn.active {
  background: var(--blue);
  color: var(--white);
  border-color: var(--blue);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== DESTINATION / PROPERTY CARDS ===== */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}
.card-grid-3 { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); }
.card-grid-5 { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
.dest-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-100);
  transition: box-shadow var(--transition), transform var(--transition);
}
.dest-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.dest-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #cdd5e0 0%, #a8b5c8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
  font-size: 13px;
  font-weight: 500;
  position: relative;
  overflow: hidden;
}
.dest-card-img::after {
  content: attr(data-label);
  position: absolute;
  font-size: 12px;
  color: var(--white);
  background: rgba(0,0,0,.35);
  padding: 4px 10px;
  border-radius: 4px;
}
.dest-card-body { padding: 16px; }
.dest-card-body h3 { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.dest-card-body .location { font-size: 13px; color: var(--gray-500); margin-bottom: 8px; }
.dest-card-body .meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.rating-badge {
  background: var(--navy);
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  line-height: 1;
}
.rating-text { font-size: 13px; color: var(--gray-500); }
.price-line { margin-top: 10px; text-align: right; }
.price-original {
  font-size: 13px;
  color: var(--gray-500);
  text-decoration: line-through;
  margin-right: 4px;
}
.price-current { font-size: 18px; font-weight: 700; color: var(--gray-900); }
.price-note { font-size: 12px; color: var(--gray-500); }
.duration-badge {
  background: #e8f0fe;
  color: var(--blue);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
}

/* ===== CAROUSEL ===== */
.carousel-wrapper {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 4px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track .dest-card { min-width: 260px; flex-shrink: 0; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--gray-200);
  background: var(--white);
  box-shadow: var(--shadow-md);
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: all var(--transition);
  color: var(--gray-700);
}
.carousel-btn:hover { background: var(--gray-50); box-shadow: var(--shadow-lg); }
.carousel-btn.prev { left: 8px; }
.carousel-btn.next { right: 8px; }

/* ===== TRENDING / SIMPLE CARDS ===== */
.trending-grid {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.trending-card {
  flex: 1;
  min-width: 180px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #2d5a9e 0%, #1a3a6e 100%);
  display: flex;
  align-items: flex-end;
  transition: transform var(--transition);
}
.trending-card:hover { transform: scale(1.02); }
.trending-card span {
  padding: 16px;
  color: var(--white);
  font-size: 20px;
  font-weight: 700;
  text-shadow: 0 2px 8px rgba(0,0,0,.4);
  width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,.45));
}

/* Explore dest compact */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.explore-item {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-100);
  transition: box-shadow var(--transition);
}
.explore-item:hover { box-shadow: var(--shadow-sm); }
.explore-thumb {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, #cdd5e0 0%, #a8b5c8 100%);
  flex-shrink: 0;
}
.explore-info h3 { font-size: 15px; font-weight: 600; }
.explore-info p { font-size: 13px; color: var(--gray-500); }

/* ===== LOYALTY CTA ===== */
.loyalty-banner {
  background: linear-gradient(135deg, var(--navy) 0%, #004bb5 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.loyalty-banner h2 { font-size: 28px; font-weight: 800; margin-bottom: 4px; }
.loyalty-banner h3 { font-size: 18px; font-weight: 600; margin-bottom: 8px; opacity: .9; }
.loyalty-banner p { font-size: 14px; opacity: .8; max-width: 500px; }
.loyalty-actions { display: flex; gap: 12px; margin-top: 16px; }

/* ===== POPULAR LINKS ===== */
.links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
}
.links-grid a {
  font-size: 14px;
  color: var(--blue);
  padding: 4px 0;
}

/* ===== FAQ ACCORDION ===== */
.accordion { max-width: 800px; }
.accordion-item {
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  margin-bottom: 8px;
  overflow: hidden;
}
.accordion-header {
  width: 100%;
  background: var(--white);
  border: none;
  padding: 18px 20px;
  font-size: 15px;
  font-weight: 600;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  transition: background var(--transition);
}
.accordion-header:hover { background: var(--gray-50); }
.accordion-chevron {
  width: 20px;
  height: 20px;
  transition: transform 0.3s ease;
  flex-shrink: 0;
  color: var(--gray-500);
}
.accordion-item.open .accordion-chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.accordion-item.open .accordion-body {
  max-height: 300px;
  padding: 0 20px 18px;
}
.accordion-body p { font-size: 14px; color: var(--gray-500); line-height: 1.6; }

/* ===== RENTAL COMPANIES ===== */
.company-grid {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}
.company-logo {
  width: 120px;
  height: 60px;
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--gray-700);
  transition: box-shadow var(--transition);
}
.company-logo:hover { box-shadow: var(--shadow-sm); }

/* ===== CREDIT CARD PROMO ===== */
.promo-banner {
  background: linear-gradient(135deg, #003B95 0%, #0057b8 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.promo-banner h3 { font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.promo-banner p { font-size: 14px; opacity: .85; }

/* ===== ATTRACTIONS ACTIVITY CARDS ===== */
.activity-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-100);
  transition: box-shadow var(--transition), transform var(--transition);
}
.activity-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.activity-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #e0c8a8 0%, #c4a882 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  color: var(--gray-500);
}
.activity-card-body { padding: 16px; }
.activity-card-body h3 { font-size: 14px; font-weight: 600; line-height: 1.4; }
.activity-card-body .from-price { font-size: 13px; color: var(--gray-500); margin-top: 8px; }
.activity-card-body .from-price strong { color: var(--gray-900); }

/* ===== BENEFITS SECTION ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-100);
}
.benefit-icon {
  width: 56px;
  height: 56px;
  background: #e8f0fe;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  color: var(--blue);
}
.benefit-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--gray-500); }

/* ===== ACCOUNT CTA ===== */
.account-banner {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
}
.account-banner h2 { font-size: 24px; font-weight: 700; margin-bottom: 4px; }
.account-banner .sub { font-size: 16px; color: var(--gray-500); margin-bottom: 8px; }
.account-banner p { font-size: 14px; color: var(--gray-500); margin-bottom: 20px; }
.account-actions { display: flex; gap: 12px; justify-content: center; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,.8);
  padding: 48px 0 24px;
  font-size: 13px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  color: var(--white);
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  color: rgba(255,255,255,.7);
  padding: 4px 0;
  font-size: 13px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); text-decoration: none; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.15);
  padding-top: 24px;
  text-align: center;
  font-size: 12px;
  opacity: .6;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .hero h1 { font-size: 26px; }
  .search-bar { flex-direction: column; }
  .search-field { min-width: 100%; }
  .loyalty-banner { padding: 24px; text-align: center; justify-content: center; }
  .loyalty-actions { justify-content: center; }
  .promo-banner { flex-direction: column; text-align: center; }
  .trending-grid { flex-direction: column; }
  .trending-card { aspect-ratio: 16/7; }
  .card-grid { grid-template-columns: 1fr 1fr; }
  .explore-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .header-actions .btn-outline.hide-mobile { display: none; }
}
@media (max-width: 480px) {
  .card-grid { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: 1fr; }
  .radio-group { flex-direction: column; gap: 8px; }
}

